package lab.genai.springbootlangchain4j.service;

import dev.langchain4j.service.MemoryId;
import dev.langchain4j.service.Result;
import dev.langchain4j.service.SystemMessage;
import dev.langchain4j.service.TokenStream;
import dev.langchain4j.service.UserMessage;

/**
 * LangChain4j AI service. The implementation is generated by {@code AiServices}; each
 * {@code sessionId} gets its own conversation memory.
 */
public interface ChatAssistant {

    String SYSTEM_PROMPT = """
            You are a helpful, friendly assistant in a chat application.
            Answer clearly and concisely. Use Markdown when it helps readability.
            If you don't know something, say so instead of guessing.
            """;

    /** Returns {@link Result} (not plain String) so the caller can log token usage and finish reason. */
    @SystemMessage(SYSTEM_PROMPT)
    Result<String> chat(@MemoryId String sessionId, @UserMessage String message);

    @SystemMessage(SYSTEM_PROMPT)
    TokenStream streamChat(@MemoryId String sessionId, @UserMessage String message);
}
